// src/data/products.js (Dữ liệu giả lập)

const mockProductDetail = {
    id: 'POHTK404',
    name: 'ÁO POLO NAM POHTK404',
    price: '379.000',
    description: 'Chất liệu: PIQUE. Đặc tính: 70% COTTON, 27% POLY, 3% SPANDEX. Form: REGULAR.',
    colors: [
        { name: 'Đen', code: '#000000', image: 'path/to/black_thumb.jpg' },
        { name: 'Trắng', code: '#FFFFFF', image: 'path/to/white_thumb.jpg' },
        { name: 'Be', code: '#F5F5DC', image: 'path/to/be_thumb.jpg' },
    ],
    sizes: ['M', 'L', 'XL'],
    images: [
        '../assets/images/product-main-1.jpg', // Thay bằng đường dẫn ảnh thật của bạn
        '../assets/images/product-thumb-1.jpg',
        '../assets/images/product-thumb-2.jpg',
    ],
    relatedProducts: [1, 2, 3, 4] // ID sản phẩm liên quan
};

// Hàm giả lập lấy chi tiết sản phẩm
export const fetchProductDetail = (productId) => {
    // Trong thực tế, hàm này sẽ gọi API backend
    return new Promise((resolve) => {
        setTimeout(() => {
            resolve(mockProductDetail);
        }, 500);
    });
};

// Dữ liệu sản phẩm dùng cho các section (đã có trong Section2, Section3)
export const mockSectionProducts = [
    { id: 1, name: "Áo polo nam POHTK401", price: "479.000", image: '../assets/images/product-1.jpg' },
    { id: 2, name: "Áo polo nam POHTK402", price: "479.000", image: '../assets/images/product-2.jpg' },
    { id: 3, name: "Áo polo nam POHTK403", price: "479.000", image: '../assets/images/product-3.jpg' },
    { id: 4, name: "Áo polo nam POHTK404", price: "479.000", image: '../assets/images/product-4.jpg' },
];
